WITH web_events_by_session AS (SELECT session_id, SUM(CASE WHEN page = '/checkout' THEN duration_sec ELSE 0 END) AS checkout_duration_sec, MIN(duration_sec) AS min_duration_sec FROM web_events GROUP BY session_id) SELECT s.id, s.customer_id, s.browser, webs.checkout_duration_sec, webs.min_duration_sec FROM sessions s LEFT JOIN web_events_by_session webs ON s.id = webs.session_id WHERE webs.checkout_duration_sec > 43 ORDER BY browser;
